from itertools import combinations, product
import heapq


def _quota_intervals(data, capacity, tie):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    if mandatory & blocked or len(mandatory) > k:
        return {"error": "impossible"}
    best_ids = None
    best_value = None
    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids) or ids & blocked:
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        valid = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > capacity:
                valid = False
                break
        if not valid:
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and
                 (selected < best_ids if tie == "smallest" else selected > best_ids))):
            best_ids, best_value = selected, value
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _build_quota_solver(capacity, tie):
    return lambda data: _quota_intervals(data, capacity, tie)


def _component_06(data):
    def rounded(n, mode):
        if mode == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), data["rounding"])
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    domains = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        domains.append([-1] + versions)

    best = None
    best_versions = None
    for assignment in product(*domains):
        selected = {name: version for name, version in zip(names, assignment)
                    if version != -1}
        rows_by_name = {}
        feasible = True
        for name, version in selected.items():
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                feasible = False
                break
            rows_by_name[name] = next(row for row in packages[name]
                                      if row["version"] == version)
        if not feasible:
            continue
        for name, (low, high) in roots.items():
            if name not in selected or not low <= selected[name] <= high:
                feasible = False
                break
        if not feasible:
            continue

        edges = {name: [] for name in selected}
        reachable = set()
        pending = list(roots)
        while pending and feasible:
            name = pending.pop()
            if name in reachable:
                continue
            version = selected.get(name)
            if version is None:
                feasible = False
                break
            reachable.add(name)
            row = rows_by_name[name]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                other_version = selected.get(other)
                if other_version is None or not dep["min"] <= other_version <= dep["max"]:
                    feasible = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not feasible or reachable != set(selected):
            continue

        state = {}
        def acyclic(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in edges.get(name, []):
                if not acyclic(other):
                    return False
            state[name] = 2
            return True
        if not all(acyclic(name) for name in edges):
            continue

        vector = tuple(selected.get(name, -1) for name in names)
        if best is None or vector < best:
            best = vector
            best_versions = selected
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    start_mask = bit.get(source, 0)
    initial = (source, start_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, start_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(depart + edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((depart + duration, remaining - 1))
            for arrival, next_remaining in choices:
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": _build_quota_solver(1, "smallest"),
    "component_02": _build_quota_solver(2, "smallest"),
    "component_03": _build_quota_solver(1, "largest"),
    "component_04": _build_quota_solver(2, "largest"),
    "component_05": _build_quota_solver(1, "smallest"),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}
